          "note": "**恋爱大师分析五：** 普通见面之后，周叙短暂地想从紫桐的“目前没有”里听到更大的保证。这是他的焦虑露头，不是关系已经出了问题。紫桐没有用安慰承诺把他的焦虑抹平，也没有冷处理，而是明确说出“愿意继续”和“不是免检资格”同时成立。稳定联系的核心并非消灭风险，而是允许风险被说出来，并让对方不用立刻交出未来作为抵押。 中午周叙确实发了狗的照片，紫桐没有马上回。下午她只回了一个笑脸。周叙没有把这个笑脸当作她已经恢复精神，晚上她才说阿雯今天去上班了，情绪还是差，但没有再说自己可笑。她还说：“我发现陪朋友也不是要负责让她立刻好起来。”周叙回：“这句话也适合放在很多关系里。”她说：“别拿我的话做你的金句库。” 他后面花了四十分钟改简历，没有把整份发给她请她检查。第二天面试前，他只发了一句：“我去试试，结果晚点说。”紫桐回：“好，去试试。”这句没有多余的鼓励，却让他在电梯里站直了一点。",
