          "searchExcerpt": "独处不是撤回感情，也不是等待伴侣强行突破的暗号。夏紫桐保留拒绝见面、调整媒介和不公开全部行程的权利；周叙保留失望、安排朋友活动和无法随叫随到的权利。边界不是隔绝，而是让靠近拥有真实同意。有限、可执行的承诺，通常比我永远都在更能积累安全感。"
