          "note": "两个人都可以说“我只能听十分钟”或“我今天完全接不住”。明确容量不是冷漠，而是避免硬撑之后迁怒。与此同时，长期只撤退、不修复也会侵蚀关系，所以边界必须与责任并存。伴侣不是彼此的治疗师，却仍可以在自愿和有余力时提供情感支持，并在能力不足时把支持网络补齐。",
