          "correction": "",
          "note": "临时取消不是谁的道德考试。夏紫桐有家事，也有提前沟通和共同承担费用的责任；周叙有失望，也有表达失望而不把它变成指责的责任。真正成熟的回应不是“永远没关系”，而是能说出“这对我有影响，但我不把影响变成你的罪”。当双方都不再用体谅来隐藏情绪，取消一次约定就不必升级成对关系的判决。 七月初，周叙收到杭州一家软件公司的正式意向。职位比现在更接近产品经理，薪资高出近四成，团队看起来也更正规。代价是前三个月需要高频出差，转正后大概率搬去杭州；如果他拒绝，现公司的项目虽然还有，但升职和加薪都没有明确时间。 他把邮件看了三遍，没有马上告诉夏紫桐。他不是想隐瞒，只是害怕一开口，自己还没想清楚的事就会变成两个人必须立刻回答的问题。 夏紫桐把手机屏幕扣在桌上。她那天刚收到一个本市公共健康项目的续约邀请，职位不是升职，却能让她负责一条完整的内容线，工作时间相对规律。她原本想等周叙说完再讲，听到“以后”两个字，还是先开了口。",
