          "note": "职业和城市分歧最怕被翻译成“谁更爱谁”。周叙想去更好的岗位，不等于不重视关系；夏紫桐希望留在长沙，也不等于缺少野心。难点在于每个人的选择都会产生共同后果，因此“这是我自己的事”不能用来逃避告知，“为了我们”也不能用来要求对方牺牲。此刻他们没有达成一致，却完成了重要的一步：把事实、愿望、担心和不能接受的部分分开。 周叙把杭州的事告诉陈放。两人在公司附近的面馆吃饭，陈放听完，第一反应是：“你就去啊。异地又不是分手，女生多适应一阵就好了。” 周叙没有立刻反驳。他知道陈放不是恶意，只是把很多事情说得太轻松。 **陈放：** 那就看她愿不愿意跟你走。你总不能为了她放弃机会。 **陈放：** 你现在说话很像她。 **陈放：** 那你们谈恋爱是不是连朋友也要一起上沟通课？ 那天晚上，周叙把这段饭局告诉了夏紫桐。说到“你现在说话很像她”时，他带着一点笑，想把气氛弄轻松。 手机安静了几秒。陈放回了一个“知道了”的表情，又补了一句：“我只是不会说话，没想替你们决定。”",
          "originalMaleReply": "那我们先把事实列出来：杭州岗位下周回复，前三个月每月至少出差两周，转正后可能搬；你的项目八月开始，至少持续一年。我们不今晚决定住哪里。",
          "originalFemaleFollowup": "先决定我们愿不愿意试三个月，而不是直接把三年写完。",
          "searchText": "恋爱大师分析：第25—30回合之后 职业和城市分歧最怕被翻译成谁更爱谁。周叙想去更好的岗位，不等于不重视关系；夏紫桐希望留在长沙，也不等于缺少野心。难点在于每个人的选择都会产生共同后果，因此这是我自己的事不能用来逃避告知，为了我们也不能用来要求对方牺牲。此刻他们没有达成一致，却完成了重要的一步：把事实、愿望、担心和不能接受的部分分开。 周叙把杭州的事告诉陈放。两人在公司附近的面馆吃饭，陈放听完，第一反应是：你就去啊。异地又不是分手，女生多适应一阵就好了。 周叙没有立刻反驳。他知道陈放不是恶意，只是把很多事情说得太轻松。 陈放： 那就看她愿不愿意跟你走。你总不能为了她放弃机会。 陈放： 你现在说话很像她。 陈放： 那你们谈恋爱是不是连朋友也要一起上沟通课？ 那天晚上，周叙把这段饭局告诉了夏紫桐。说到你现在说话很像她时，他带着一点笑，想把气氛弄轻松。 手机安静了几秒。陈放回了一个知道了的表情，又补了一句：我只是不会说话，没想替你们决定。 那我们先把事实列出来：杭州岗位下周回复，前三个月每月至少出差两周，转正后可能搬；你的项目八月开始，至少持续一年。我们不今晚决定住哪里。 先决定我们愿不愿意试三个月，而不是直接把三年写完。",
