          "searchExcerpt": "冷静期的价值不在于让一个人受惩罚，而在于让双方停止用本能反应继续扩大损伤。暂停必须有边界：从何时开始、何时回来、期间允许什么联系。周叙的成长不是我提前说了，所以你不能难过，而是承认提前说仍可能不足；夏紫桐的成长也不是我以后永远平静，而是承认自己有时会带着报复性的愿望暂停，并愿意对这部分负责。修复从来不是把情绪抹平，而是让情绪不再替双方做全部决定。 暂停之后，他们没有立刻决定长期去留。周叙在杭州进入试用期，工作确实比以前更接近他想做的事，但加班也比招聘时说的多。夏紫桐的长沙项目开始后，常常要去社区做调研，周末也有活动。 他们在一个月后见面。高铁站人很多，周叙没有在出口拥抱她，只在她走近时问：可以抱一下吗？夏紫桐点头，抱了他三秒就松开。 接下来的几周，他们没有发生戏剧性的大和好。周叙仍会在会议结束后忘记看手机，夏紫"
