          "searchExcerpt": "这一段没有把每次交流都变成关系建设。大量无关紧要的闲聊让两个人仍是具体生活中的人，而不是轮流完成沟通作业。边界有效的标志也不是对方毫无失落，而是失落可以被承认，却不被用来迫使另一方撤回选择。 周叙没有接受驻场，但这并不自动消除夏紫桐被排除在外的感受；夏紫桐承认自己看见半封邮件便下了结论，也没有要求一句道歉抹平余波。"
